	err := runWhy(ctx, &out, &bytes.Buffer{}, whyOptions{Path: "file.go", NoPager: true})
	if err != nil {
		t.Fatalf("runWhy() error = %v", err)
	}

	assertWhyOutputContains(t, out.String(),
