package cli

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"strings"

	"github.com/charmbracelet/bubbles/key"
	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/entireio/cli/cmd/entire/cli/api"
)

// activityDataMsg is sent when API data has been fetched.
type activityDataMsg struct {
	stats  contributionStats
	repos  []repoContribution
	hourly []hourlyPoint
	days   []commitDay
}

// activityErrMsg is sent when fetching fails.
type activityErrMsg struct{ err error }

type activityModel struct {
	// Data (nil until loaded)
	stats  *contributionStats
	repos  []repoContribution
	hourly []hourlyPoint
	days   []commitDay

	// Loading state
	loading bool
	loadErr error
	spinner spinner.Model

	// Fetch context
	ctx    context.Context
	client *api.Client

	// View state
	viewport viewport.Model
	sty      activityStyles
	useColor bool
	width    int
	height   int
	ready    bool
}

func runActivityTUI(ctx context.Context, client *api.Client) error {
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))

	m := activityModel{
		loading:  true,
		spinner:  sp,
		ctx:      ctx,
		client:   client,
		useColor: shouldUseColor(os.Stdout),
	}
	p := tea.NewProgram(m, tea.WithAltScreen())
	if _, err := p.Run(); err != nil {
		return fmt.Errorf("activity TUI: %w", err)
	}
	return nil
}

func (m activityModel) fetchData() tea.Msg { //nolint:ireturn // bubbletea Cmd signature requires tea.Msg return
	activity, commits, err := fetchActivityData(m.ctx, m.client)
	if err != nil {
		return activityErrMsg{err: err}
	}

	return activityDataMsg{
		stats: contributionStats{
			Tasks:         activity.Stats.Tasks,
			Throughput:    activity.Stats.Throughput,
			Iteration:     activity.Stats.Iteration,
			ContinuityH:   activity.Stats.ContinuityHours,
			Streak:        activity.Stats.LifetimeStreak,
			CurrentStreak: activity.Stats.LifetimeCurrentStreak,
		},
		repos:  activity.Repos,
		hourly: activity.HourlyContributions,
		days:   groupCommitsByDay(commits),
	}
}

func (m activityModel) Init() tea.Cmd {
	return tea.Batch(m.spinner.Tick, m.fetchData)
}

func (m activityModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea interface
	switch msg := msg.(type) {
	case activityDataMsg:
		m.loading = false
		m.stats = &msg.stats
		m.repos = msg.repos
		m.hourly = msg.hourly
		m.days = msg.days
		if m.width > 0 {
			m = m.withViewport()
		}
		return m, nil

	case activityErrMsg:
		m.loading = false
		m.loadErr = msg.err
		return m, nil

	case tea.KeyMsg:
		if key.Matches(msg, keys.Quit) || key.Matches(msg, keys.Back) {
			return m, tea.Quit
		}
		if key.Matches(msg, keys.Home) {
			if m.ready {
				m.viewport.GotoTop()
			}
			return m, nil
		}
		if key.Matches(msg, keys.End) {
			if m.ready {
				m.viewport.GotoBottom()
			}
			return m, nil
		}

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.sty = newActivityStylesWithWidth(m.width, m.useColor)
		if m.stats != nil {
			m = m.withViewport()
		}
		return m, nil

	case spinner.TickMsg:
		if m.loading {
			var cmd tea.Cmd
			m.spinner, cmd = m.spinner.Update(msg)
			return m, cmd
		}
	}

	if m.ready {
		var cmd tea.Cmd
		m.viewport, cmd = m.viewport.Update(msg)
		return m, cmd
	}

	return m, nil
}

func (m activityModel) withViewport() activityModel {
	headerHeight := m.headerLineCount()
	vpHeight := m.height - headerHeight - 1
	if vpHeight < 1 {
		vpHeight = 1
	}

	if !m.ready {
		m.viewport = viewport.New(m.width, vpHeight)
		m.ready = true
	} else {
		m.viewport.Width = m.width
		m.viewport.Height = vpHeight
	}
	m.viewport.SetContent(m.renderCommits())
	return m
}

func (m activityModel) View() string {
	if m.loadErr != nil {
		return fmt.Sprintf("\n  Failed to load activity: %s\n\n  Press q to quit.\n", m.loadErr)
	}

package cli

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"time"

	"github.com/charmbracelet/lipgloss"
	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/interactive"

	"golang.org/x/term"
)

// statusStyles holds pre-built lipgloss styles and terminal metadata.
type statusStyles struct {
	colorEnabled bool
	width        int

	// Styles
	green  lipgloss.Style
	red    lipgloss.Style
	gray   lipgloss.Style
	bold   lipgloss.Style
	dim    lipgloss.Style
	agent  lipgloss.Style // amber/orange for agent names
	cyan   lipgloss.Style
	yellow lipgloss.Style // yellow for stale warnings
}

// newStatusStyles creates styles appropriate for the output writer.
func newStatusStyles(w io.Writer) statusStyles {
	useColor := shouldUseColor(w)
	width := getTerminalWidth(w)

	s := statusStyles{
		colorEnabled: useColor,
		width:        width,
	}

	if useColor {
		s.green = lipgloss.NewStyle().Foreground(lipgloss.Color("2"))
		s.red = lipgloss.NewStyle().Foreground(lipgloss.Color("1"))
		s.gray = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
		s.bold = lipgloss.NewStyle().Bold(true)
		s.dim = lipgloss.NewStyle().Faint(true)
		s.agent = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("214"))
		s.cyan = lipgloss.NewStyle().Foreground(lipgloss.Color("6"))
		s.yellow = lipgloss.NewStyle().Foreground(lipgloss.Color("3"))
	}

	return s
}

// render applies a style to text only when color is enabled.
func (s statusStyles) render(style lipgloss.Style, text string) string {
	if !s.colorEnabled {
		return text
	}
	return style.Render(text)
}

// shouldUseColor returns true if the writer supports color output.
func shouldUseColor(w io.Writer) bool {
	if os.Getenv("NO_COLOR") != "" {
		return false
	}
	return interactive.IsTerminalWriter(w)
}

// getTerminalWidth returns the terminal width, capped at 80 with a fallback of 60.
// It first checks the writer itself, then falls back to Stdout/Stderr.
func getTerminalWidth(w io.Writer) int {
	// Try the output writer first
	if f, ok := w.(*os.File); ok {
		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
			return min(width, 80)
		}
	}

	// Fall back to Stdout, then Stderr
	for _, f := range []*os.File{os.Stdout, os.Stderr} {
		if f == nil {
			continue
		}
		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
			return min(width, 80)
		}
	}

	return 60
}

// formatTokenCount formats a token count for display.
// 0 → "0", 500 → "500", 1200 → "1.2k", 14300 → "14.3k"
func formatTokenCount(n int) string {
	if n < 1000 {
		return strconv.Itoa(n)
	}
	f := float64(n) / 1000.0
	s := fmt.Sprintf("%.1f", f)
	// Remove trailing ".0" for clean display (e.g., 1000 → "1k" not "1.0k")
	s = strings.TrimSuffix(s, ".0")
	return s + "k"
}

// totalTokens recursively sums all token fields including subagent tokens.
func totalTokens(tu *agent.TokenUsage) int {
	if tu == nil {
		return 0
	}
	total := tu.InputTokens + tu.CacheCreationTokens + tu.CacheReadTokens + tu.OutputTokens
	total += totalTokens(tu.SubagentTokens)
	return total
}

// horizontalRule renders a dimmed horizontal rule of the given width.
func (s statusStyles) horizontalRule(width int) string {
	rule := strings.Repeat("─", width)
	return s.render(s.dim, rule)
}

// sectionRule renders a section header like: ── Active Sessions ────────────
func (s statusStyles) sectionRule(label string, width int) string {
	prefix := "── "
	content := label + " "
	usedWidth := len([]rune(prefix)) + len([]rune(content))
	trailing := width - usedWidth
	if trailing < 1 {
		trailing = 1
	}

	var b strings.Builder
	b.WriteString(s.render(s.dim, "── "))
	b.WriteString(s.render(s.dim, label))
	b.WriteString(" ")
	b.WriteString(s.render(s.dim, strings.Repeat("─", trailing)))

