	}
	return contextWithSpan(ctx, s), s
}

// RecordError marks the span as errored. Only the first non-nil error is stored;
// subsequent calls are no-ops. Call this before End() on error paths.
func (s *Span) RecordError(err error) {
	if err == nil || s.err != nil {
		return
	}
	s.err = err
}

// End completes the span. For root spans, emits a single DEBUG log line
// with the full timing tree. For child spans, records the duration only.
// Safe to call multiple times -- subsequent calls are no-ops.
func (s *Span) End() {
	if s.ended {
		return
	}
	s.ended = true
	s.duration = time.Since(s.start)

	// Only root spans emit log output
	if s.parent != nil {
		return
	}

	// Build log attributes: op, duration_ms, error flag, then child step durations.
	// Component is set via context so it appears exactly once in the log line.
	logCtx := logging.WithComponent(s.ctx, "perf")
	grandchildren := 0
	for _, c := range s.children {
		grandchildren += len(c.children)
	}
	attrs := make([]any, 0, 3+2*len(s.children)+2*grandchildren+len(s.attrs))
	attrs = append(attrs, slog.String("op", s.name))
	attrs = append(attrs, slog.Int64("duration_ms", s.duration.Milliseconds()))
	if s.err != nil {
		attrs = append(attrs, slog.Bool("error", true))
	}

	lines, err := parseBlamePorcelain(blameOutput)
	if err != nil {
		parseSpan.RecordError(err)
		parseSpan.End()
		return whyViewData{}, fmt.Errorf("parse git blame output: %w", err)
	}
	parseSpan.End()

	_, buildRowsSpan := perf.Start(ctx, "build_rows")
	blocks := collapseWhyBlameBlocks(lines)
	rows := buildWhyBlameRows(lines, blocks)
	buildRowsSpan.End()

	_, openRepoSpan := perf.Start(ctx, "open_repository")
	repo, err := openRepository(ctx)
	if err != nil {
		openRepoSpan.RecordError(err)
		openRepoSpan.End()
		return whyViewData{}, fmt.Errorf("open repository: %w", err)
	}
	openRepoSpan.End()

	_, lookupSpan := perf.Start(ctx, "init_checkpoint_lookup")
	lookup, err := newWhyCheckpointLookup(ctx, repo)
	if err != nil {
		lookupSpan.RecordError(err)
		lookupSpan.End()
		return whyViewData{}, fmt.Errorf("initialize checkpoint lookup: %w", err)
	}
	lookupSpan.End()

	_, enrichSpan := perf.Start(ctx, "enrich_commits")
	commits := enrichWhyCommits(ctx, repo, lookup, blocks)
	enrichSpan.End()

	return whyViewData{
		GitPath: gitPath,
		Rows:    rows,
		Blocks:  blocks,
		Commits: commits,
	}, nil
}

