		ti.PlaceholderStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
		ti.Cursor.Style = lipgloss.NewStyle().Foreground(lipgloss.Color(searchAccentOrange))
	}

	var apiPage int
	if results != nil {
		apiPage = 1
	}

	m := searchModel{
