	case activityErrMsg:
		m.loading = false
		m.loadErr = msg.err
		return m, nil

	case tea.KeyMsg:
		if key.Matches(msg, keys.Quit) || key.Matches(msg, keys.Back) {
			return m, tea.Quit
		}
		if key.Matches(msg, keys.Home) {
			if m.ready {
				m.viewport.GotoTop()
			}
			return m, nil
		}
		if key.Matches(msg, keys.End) {
			if m.ready {
				m.viewport.GotoBottom()
			}
			return m, nil
		}

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.sty = newActivityStylesWithWidth(m.width, m.useColor)
		if m.stats != nil {
