func padLeft(n int) string {
	s := strings.Builder{}
	if n < 10 {
		s.WriteString("  ")
	} else if n < 100 {
		s.WriteString(" ")
	}
	fmt.Fprintf(&s, "%d", n)
	return s.String()
}

