package cli

import (
	"bytes"
	"context"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
	"time"
)

type whyBlameLine struct {
	CommitHash   string
	OriginalLine int
	FinalLine    int
	Author       string
	AuthorTime   time.Time
	Filename     string
	Source       string
}

type whyBlameBlock struct {
	CommitHash string
	StartLine  int
	EndLine    int
	StartRow   int
	EndRow     int
}

type whyBlameRow struct {
	whyBlameLine

	BlockIndex int
}

type whyBlameMetadata struct {
	Author     string
	AuthorTime time.Time
	Filename   string
}

func runGitBlame(ctx context.Context, repoRoot, gitPath string) ([]byte, error) {
	cmd := exec.CommandContext(ctx, "git", "blame", "--line-porcelain", "--", gitPath)
	cmd.Dir = repoRoot

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		details := strings.TrimSpace(stderr.String())
		if details == "" {
			return nil, fmt.Errorf("git blame failed for %s: %w", gitPath, err)
		}
		return nil, fmt.Errorf("git blame failed for %s: %w: %s", gitPath, err, details)
	}

	return stdout.Bytes(), nil
}

func parseBlamePorcelain(data []byte) ([]whyBlameLine, error) {
	if len(data) == 0 {
		return nil, nil
	}

	rawLines := bytes.Split(bytes.TrimSuffix(data, []byte{'\n'}), []byte{'\n'})
	metadataByCommit := make(map[string]whyBlameMetadata)
	lines := make([]whyBlameLine, 0)

	var current *whyBlameLine
	for lineNumber, raw := range rawLines {
		line := strings.TrimSuffix(string(raw), "\r")

		if hash, originalLine, finalLine, ok, err := parseBlameHeader(line); err != nil {
			return nil, fmt.Errorf("parse blame header on line %d: %w", lineNumber+1, err)
		} else if ok {
			if current != nil {
				return nil, fmt.Errorf("blame record for %s:%d missing source line", current.CommitHash, current.FinalLine)
			}
			next := whyBlameLine{
				CommitHash:   hash,
				OriginalLine: originalLine,
				FinalLine:    finalLine,
			}
			if metadata, exists := metadataByCommit[hash]; exists {
				applyBlameMetadata(&next, metadata)
			}
			current = &next
			continue
		}

		if current == nil {
			if strings.TrimSpace(line) == "" {
				continue
			}
			return nil, fmt.Errorf("blame metadata without header on line %d", lineNumber+1)
		}

		if strings.HasPrefix(line, "\t") {
			current.Source = strings.TrimPrefix(line, "\t")
			lines = append(lines, *current)
			metadataByCommit[current.CommitHash] = metadataFromBlameLine(*current)
			current = nil
			continue
		}

		if err := applyBlameMetadataLine(current, line); err != nil {
			return nil, fmt.Errorf("parse blame metadata on line %d: %w", lineNumber+1, err)
		}
		metadataByCommit[current.CommitHash] = metadataFromBlameLine(*current)
	}

	if current != nil {
		return nil, fmt.Errorf("blame record for %s:%d missing source line", current.CommitHash, current.FinalLine)
	}

	return lines, nil
}

func parseBlameHeader(line string) (string, int, int, bool, error) {
	fields := strings.Fields(line)
	if len(fields) < 3 || !isBlameHash(fields[0]) {
		return "", 0, 0, false, nil
	}

	originalLine, err := strconv.Atoi(fields[1])
	if err != nil {
		return "", 0, 0, false, fmt.Errorf("invalid original line %q", fields[1])
	}
	finalLine, err := strconv.Atoi(fields[2])
	if err != nil {
		return "", 0, 0, false, fmt.Errorf("invalid final line %q", fields[2])
	}

	return fields[0], originalLine, finalLine, true, nil
}

func isBlameHash(value string) bool {
	if len(value) < 7 {
		return false
	}
	for _, r := range value {
		if (r < '0' || r > '9') && (r < 'a' || r > 'f') && (r < 'A' || r > 'F') {
			return false
		}
	}
	return true
}

func applyBlameMetadataLine(line *whyBlameLine, metadata string) error {
	switch {
	case strings.HasPrefix(metadata, "author "):
		line.Author = strings.TrimPrefix(metadata, "author ")
	case strings.HasPrefix(metadata, "author-time "):
		raw := strings.TrimPrefix(metadata, "author-time ")
		seconds, err := strconv.ParseInt(raw, 10, 64)
		if err != nil {
			return fmt.Errorf("invalid author-time %q", raw)
		}
		line.AuthorTime = time.Unix(seconds, 0)
	case strings.HasPrefix(metadata, "filename "):
		line.Filename = strings.TrimPrefix(metadata, "filename ")
	}
	return nil
}

func metadataFromBlameLine(line whyBlameLine) whyBlameMetadata {
	return whyBlameMetadata{
		Author:     line.Author,
		AuthorTime: line.AuthorTime,
		Filename:   line.Filename,
	}
}

func applyBlameMetadata(line *whyBlameLine, metadata whyBlameMetadata) {
	line.Author = metadata.Author
	line.AuthorTime = metadata.AuthorTime
	line.Filename = metadata.Filename
}

func collapseWhyBlameBlocks(lines []whyBlameLine) []whyBlameBlock {
	if len(lines) == 0 {
		return nil
	}

	blocks := make([]whyBlameBlock, 0)
	current := whyBlameBlock{
		CommitHash: lines[0].CommitHash,
		StartLine:  lines[0].FinalLine,
		EndLine:    lines[0].FinalLine,
		StartRow:   0,
		EndRow:     0,
	}

	for i := 1; i < len(lines); i++ {
		line := lines[i]
		if line.CommitHash == current.CommitHash {
			current.EndLine = line.FinalLine
			current.EndRow = i
			continue
		}

		blocks = append(blocks, current)
		current = whyBlameBlock{
			CommitHash: line.CommitHash,
			StartLine:  line.FinalLine,
			EndLine:    line.FinalLine,
			StartRow:   i,
			EndRow:     i,
		}
	}

	blocks = append(blocks, current)
	return blocks
}

func buildWhyBlameRows(lines []whyBlameLine, blocks []whyBlameBlock) []whyBlameRow {
	rows := make([]whyBlameRow, len(lines))
	for i, line := range lines {
		rows[i] = whyBlameRow{whyBlameLine: line}
	}
	for blockIndex, block := range blocks {
		for rowIndex := block.StartRow; rowIndex <= block.EndRow && rowIndex < len(rows); rowIndex++ {
			rows[rowIndex].BlockIndex = blockIndex
		}
	}
	return rows
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/trailers"
	"github.com/entireio/cli/perf"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

const whyNotGeneratedSummary = "(not generated)"

type whyCheckpointLookup struct {
	repo                *git.Repository
	v1Store             *checkpoint.GitStore
	v2Store             *checkpoint.V2GitStore
	preferCheckpointsV2 bool
}

type whyCommitInfo struct {
	Hash             plumbing.Hash
	Subject          string
	Author           string
	AuthorTime       time.Time
	CheckpointID     id.CheckpointID
	Checkpoint       whyCheckpointInfo
	Summary          string
	SummaryGenerated bool
}

type whyCheckpointInfo struct {
	Found            bool
	Agent            types.AgentType
	SessionCount     int
	FilesTouched     []string
	Summary          string
	SummaryGenerated bool
}

type whySessionMetadataAndPromptsReader interface {
	ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.SessionContent, error)
}

func newWhyCheckpointLookup(ctx context.Context, repo *git.Repository) (*whyCheckpointLookup, error) {
	if repo == nil {
		var err error
		repo, err = openRepository(ctx)
		if err != nil {
			return nil, fmt.Errorf("not a git repository: %w", err)
		}
	}

	return &whyCheckpointLookup{
		repo:                repo,
		v1Store:             checkpoint.NewGitStore(repo),
		v2Store:             checkpoint.NewV2GitStore(repo, ""),
		preferCheckpointsV2: settings.IsCheckpointsV2Enabled(ctx),
	}, nil
}

func enrichWhyCommits(ctx context.Context, repo *git.Repository, lookup *whyCheckpointLookup, blocks []whyBlameBlock) map[plumbing.Hash]whyCommitInfo {
	infoByCommit := make(map[plumbing.Hash]whyCommitInfo)
	if repo == nil {
		return infoByCommit
	}
	if lookup == nil {
		var err error
		lookup, err = newWhyCheckpointLookup(ctx, repo)
		if err != nil {
			lookup = nil
		}
	}

	loopCtx, enrichCommitLoop := perf.StartLoop(ctx, "why_enrich_commit")
	defer enrichCommitLoop.End()

	for _, block := range blocks {
		if err := ctx.Err(); err != nil {
			return infoByCommit
		}

		hash := plumbing.NewHash(block.CommitHash)
		if _, exists := infoByCommit[hash]; exists {
			continue
		}

		_, iterSpan := enrichCommitLoop.Iteration(loopCtx)

		_, commitObjectSpan := perf.Start(ctx, "why_commit_object")
		commit, err := repo.CommitObject(hash)
		if err != nil {
			commitObjectSpan.RecordError(err)
			commitObjectSpan.End()
			iterSpan.RecordError(err)
			iterSpan.End()
			continue
		}
		commitObjectSpan.End()

		subject := whyCommitSubject(commit.Message)
		info := whyCommitInfo{
			Hash:       hash,
			Subject:    subject,
			Author:     commit.Author.Name,
			AuthorTime: commit.Author.When,
			Summary:    subject,
		}

		_, checkpointTrailerSpan := perf.Start(ctx, "why_checkpoint_trailer")
		if cpID, ok := trailers.ParseCheckpoint(commit.Message); ok {
			checkpointTrailerSpan.End()
			info.CheckpointID = cpID
			_, checkpointInfoSpan := perf.Start(ctx, "why_checkpoint_info")
			if checkpointInfo, readErr := readWhyCheckpointInfo(ctx, lookup, cpID); readErr == nil {
				info.Checkpoint = checkpointInfo
				info.Summary = whyCommitFallbackSummary(checkpointInfo.Summary, subject)
				info.SummaryGenerated = checkpointInfo.SummaryGenerated
			} else {
				checkpointInfoSpan.RecordError(readErr)
			}
			checkpointInfoSpan.End()
		} else {
			checkpointTrailerSpan.End()
		}

		infoByCommit[hash] = info
		iterSpan.End()
	}

	return infoByCommit
}

func readWhyCheckpointInfo(ctx context.Context, lookup *whyCheckpointLookup, cpID id.CheckpointID) (whyCheckpointInfo, error) {
	if err := ctx.Err(); err != nil {
		return whyCheckpointInfo{}, err //nolint:wrapcheck // Propagating context cancellation
	}
	if lookup == nil {
		return whyCheckpointInfo{}, checkpoint.ErrCheckpointNotFound
	}

	_, resolveReaderSpan := perf.Start(ctx, "why_checkpoint_resolve_reader")
	reader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(
		ctx,
		cpID,
		lookup.v1Store,
		lookup.v2Store,
		lookup.preferCheckpointsV2,
	)
	if err != nil {
		resolveReaderSpan.RecordError(err)
		resolveReaderSpan.End()
		return whyCheckpointInfo{}, fmt.Errorf("resolve checkpoint reader: %w", err)
	}
	if summary == nil {
		resolveReaderSpan.RecordError(checkpoint.ErrCheckpointNotFound)
		resolveReaderSpan.End()
		return whyCheckpointInfo{}, checkpoint.ErrCheckpointNotFound
	}
	resolveReaderSpan.End()

	_, sessionContentSpan := perf.Start(ctx, "why_checkpoint_read_metadata")
	content, err := readLatestSessionMetadataAndPromptsForWhy(ctx, reader, cpID, summary)
	if err != nil && !errors.Is(err, checkpoint.ErrNoTranscript) {
		sessionContentSpan.RecordError(err)
		sessionContentSpan.End()
		return whyCheckpointInfo{}, err
	}
	sessionContentSpan.End()

	_, buildInfoSpan := perf.Start(ctx, "why_checkpoint_build_info")
	info := whyCheckpointInfo{
		Found:        true,
		SessionCount: len(summary.Sessions),
		FilesTouched: append([]string(nil), summary.FilesTouched...),
		Summary:      whyNotGeneratedSummary,
	}
	if content == nil {
		buildInfoSpan.End()
		return info, nil
	}

	info.Agent = content.Metadata.Agent
	if content.Metadata.Summary != nil {
		info.Summary = whyGeneratedSummary(content.Metadata.Summary)
		info.SummaryGenerated = true
		buildInfoSpan.End()
		return info, nil
	}
	if promptSummary, ok := whySummaryFromPrompt(content.Prompts); ok {
		info.Summary = promptSummary
	}
	buildInfoSpan.End()
	return info, nil
}

func readLatestSessionMetadataAndPromptsForWhy(ctx context.Context, reader checkpoint.CommittedReader, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) (*checkpoint.SessionContent, error) {
	if summary == nil || len(summary.Sessions) == 0 {
		return nil, checkpoint.ErrCheckpointNotFound
	}

	latestIndex := len(summary.Sessions) - 1
	if metadataReader, ok := reader.(whySessionMetadataAndPromptsReader); ok {
		content, err := metadataReader.ReadSessionMetadataAndPrompts(ctx, checkpointID, latestIndex)
		if err != nil {
			return nil, fmt.Errorf("reading session %d metadata and prompts: %w", latestIndex, err)
		}
		return content, nil
	}
	content, err := reader.ReadSessionContent(ctx, checkpointID, latestIndex)
	if err != nil {
		return nil, fmt.Errorf("reading session %d content: %w", latestIndex, err)
	}
	return content, nil
}

func whyCommitSubject(message string) string {
	for line := range strings.SplitSeq(message, "\n") {
		subject := strings.TrimSpace(line)
		if subject != "" {
			return subject
		}
	}
	return whyNotGeneratedSummary
}

func whyGeneratedSummary(summary *checkpoint.Summary) string {
	if summary == nil {
		return whyNotGeneratedSummary
	}

	parts := make([]string, 0, 2)
	if intent := strings.TrimSpace(summary.Intent); intent != "" {
		parts = append(parts, intent)
	}
	if outcome := strings.TrimSpace(summary.Outcome); outcome != "" {
		parts = append(parts, outcome)
	}
	if len(parts) == 0 {
		return whyNotGeneratedSummary
	}
	return strategy.TruncateDescription(strings.Join(parts, " - "), maxIntentDisplayLength)
}

func whySummaryFromPrompt(prompt string) (string, bool) {
	for line := range strings.SplitSeq(prompt, "\n") {
		line = strings.TrimSpace(line)
		if line != "" {
			return strategy.TruncateDescription(line, maxIntentDisplayLength), true
		}

