	}
}

func TestWhyTUIModel_FooterDocumentsVisibleControls(t *testing.T) {
	t.Parallel()

	m := testWhyTUIModel()
	footer := m.renderFooter()
	wantParts := []string{
		"↑/↓, j/k scroll",
		"home/end, g/G top/bottom",
		"q quit",
	}
	lastIndex := -1
	for _, want := range wantParts {
		idx := strings.Index(footer, want)
		if idx == -1 {
			t.Fatalf("footer missing %q: %q", want, footer)
		}
		if idx < lastIndex {
			t.Fatalf("footer control %q rendered out of order: %q", want, footer)
		}
		lastIndex = idx
	}
	if got := lipgloss.Width(footer); got != m.width {
		t.Fatalf("footer width = %d, want %d: %q", got, m.width, footer)
	}

	highlightedLines := highlightWhyCodeLines(m.data.GitPath, sourceLines, m.styles.colorEnabled)

	var b strings.Builder
	for i, row := range m.data.Rows {
		line := m.renderGutter(i, row)
		if codeWidth > 0 && i < len(highlightedLines) {
			line += highlightedLines[i]
		}
		b.WriteString(line)
		if i < len(m.data.Rows)-1 {
			b.WriteString("\n")
		}
	}
	return b.String()
}

func (m whyTUIModel) renderGutter(rowIndex int, row whyBlameRow) string {
	marker := " "
	if rowIndex == m.selected {
		marker = m.styles.render(m.styles.selectedMarker, ">")
	}

	hash := plumbing.NewHash(row.CommitHash)
	info := m.commitInfoForRow(row)
	lineNo := fmt.Sprintf("%*d", whyLineColumnWidth(m.data.Rows), row.FinalLine)
	metadata := m.renderBlameMetadata(rowIndex, row, hash, info)
	lineColumn := whyTUIColumn(lineNo, whyLineColumnWidth(m.data.Rows), m.styles.lineNo, m.styles.colorEnabled)

	return fmt.Sprintf("%s %s | %s | ", marker, metadata, lineColumn)
}

func (m whyTUIModel) renderBlameMetadata(rowIndex int, row whyBlameRow, hash plumbing.Hash, info whyCommitInfo) string {
	if !m.shouldShowBlameMetadata(rowIndex, row) {
		return strings.Repeat(" ", whyTUIMetadataWidth())
	}

	agent := whyStaticAgent(info)
	agentStyle := m.styles.agentID
	if m.styles.colorEnabled && agent != "-" {
		agentStyle = lipgloss.NewStyle().Foreground(lipgloss.Color(whyAgentDisplay(agent).Color))
	}

	columns := []string{
		whyTUIColumn(whyTUITime(row, info), whyTUITimeColumnWidth, m.styles.time, m.styles.colorEnabled),
		whyTUIColumn(whyStaticAuthor(row, info), whyTUIAuthorColumnWidth, m.styles.author, m.styles.colorEnabled),
		whyTUIColumn(whyTUIAgents(info), whyTUIAgentsColumnWidth, agentStyle, m.styles.colorEnabled),
		whyTUIColumn(whyTUICommit(hash), whyTUICommitColumnWidth, m.styles.commit, m.styles.colorEnabled),
		whyTUIColumn(whyStaticCheckpoint(info), whyTUICheckpointColumnWidth, m.styles.checkpoint, m.styles.colorEnabled),
	}
	return strings.Join(columns, " ")
}

